try:
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result1 = stats.norminvgauss(a=0.1, b=0.09).cdf(1500)
        probe("stats.norminvgauss(a=0.1, b=0.09).cdf(1500)", result1)
        if w:
            probe("stats.norminvgauss(a=0.1, b=0.09).cdf(1500)::warning", str(w[0].category.__name__) + ": " + str(w[0].message))
